pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Call setOwner with random _owner
        bool success = c.setOwner(_owner);
        // General rule: after the call, owner getter equals the argument passed (not zero unless _owner was zero)
        assertTrue(c.owner() == _owner);
    }
}

