pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0));
        address ownerBefore = c.owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeCall(c.setOwner, (newOwner)));
        address ownerAfter = c.owner();
        assertTrue((caller == ownerBefore && success && ownerAfter == newOwner) || (caller != ownerBefore && !success && ownerAfter == ownerBefore));
    }
}

